-- The shop's products with the prices and sizes from Khadija's price list (prices incl. VAT, cents).
-- Products without photos (Schwarze Seife Nilla, Maske Nilla, Kessa-Handschuh, Khol) are hidden until photos are added.
INSERT INTO categories (slug, name_de, name_en, name_ar, image, sort) VALUES ('seifen-hammam', 'Seifen & Hammam', 'Soaps & hammam', 'الصابون والحمام', '/assets/p/kaffeeseife-1.webp', 1);
INSERT INTO categories (slug, name_de, name_en, name_ar, image, sort) VALUES ('masken-peelings', 'Masken & Peelings', 'Masks & scrubs', 'الأقنعة والتقشير', '/assets/p/nila-seife-1.webp', 2);
INSERT INTO categories (slug, name_de, name_en, name_ar, image, sort) VALUES ('haar-kraeuter', 'Haar & Kräuterpulver', 'Hair & herbal powders', 'الشعر والأعشاب', '/assets/p/henna-1.webp', 3);
INSERT INTO categories (slug, name_de, name_en, name_ar, image, sort) VALUES ('oele-seren', 'Öle & Seren', 'Oils & serums', 'الزيوت والسيروم', '/assets/p/serum-2.webp', 4);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('anti-cellulite-kaffeeseife', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Kaffee-Anti-Cellulite-Seife', 'Anti-cellulite coffee soap', 'صابون القهوة المضاد للسيلوليت', 'Mit Kaffee · Handgemacht · 100 g', 'With coffee · handmade · 100 g', 'بالقهوة · صنع يدوي · 100 غ', '<h2>Das belebende Hammam-Ritual mit Kaffee</h2><p>Unsere handgemachte Kaffeeseife verbindet die marokkanische Seifentradition mit der Kraft des Kaffees. Die feinen Kaffeepartikel sorgen bei der Massage für ein sanftes Peeling-Gefühl und hinterlassen ein frisches, glattes Hautgefühl.</p><ul><li>Handgemacht in Marokko</li><li>Mit Kaffee für ein sanftes Peeling-Erlebnis</li><li>Ideal für die Massage von Oberschenkeln, Po und Armen</li><li>100 g</li></ul>', '<h2>The invigorating hammam ritual with coffee</h2><p>Our handmade coffee soap combines Moroccan soap tradition with the power of coffee. Fine coffee particles give a gentle scrub feeling during massage and leave the skin feeling fresh and smooth.</p><ul><li>Handmade in Morocco</li><li>With coffee for a gentle scrub experience</li><li>Ideal for massaging thighs, buttocks and arms</li><li>100 g</li></ul>', '<h2>طقس الحمام المنعش بالقهوة</h2><p>صابون القهوة المصنوع يدويًا يجمع بين تقاليد الصابون المغربي وقوة القهوة. حبيبات القهوة الدقيقة تمنح إحساسًا بتقشير لطيف أثناء التدليك، وتترك البشرة منتعشة وناعمة.</p><ul><li>مصنوع يدويًا في المغرب</li><li>بالقهوة لتجربة تقشير لطيفة</li><li>مثالي لتدليك الفخذين والأرداف والذراعين</li><li>100 غ</li></ul>', '<ol><li>Die Haut unter der Dusche anfeuchten.</li><li>Die Seife aufschäumen und mit kreisenden Bewegungen einmassieren.</li><li>Gründlich abspülen und anschließend Öl oder Serum auftragen.</li></ol>', '<ol><li>Wet the skin in the shower.</li><li>Lather the soap and massage it in with circular movements.</li><li>Rinse well, then apply oil or serum.</li></ol>', '<ol><li>بللي البشرة تحت الدش.</li><li>اصنعي رغوة ودلكي بحركات دائرية.</li><li>اشطفي جيدًا ثم ضعي الزيت أو السيروم.</li></ol>', '', 1000, 100, 'g', '["/assets/p/kaffeeseife-pack.webp", "/assets/p/kaffeeseife-1.webp", "/assets/p/kaffeeseife-2.webp", "/assets/p/kaffeeseife-3.webp"]', 1, 1, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('anti-cellulite-serum', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Anti-Cellulite-Serum', 'Anti-cellulite serum', 'سيروم مضاد للسيلوليت', 'Glättend · Straffend · Pflegend · 30 ml', 'Smoothing · firming · nourishing · 30 ml', 'يملس · يشد · يغذي · 30 مل', '<h2>Pflege für ein glatteres Hautbild</h2><p>Unser Serum wird bei der Massage in die Haut eingearbeitet und hinterlässt ein gepflegtes, straffes Hautgefühl. Die perfekte Ergänzung zur Kaffeeseife in Ihrem Körperritual.</p><ul><li>Kann das Hautbild sichtbar glätten</li><li>Für ein straffes, gepflegtes Hautgefühl</li><li>Leicht einzumassieren</li></ul>', '<h2>Care for smoother-looking skin</h2><p>Massaged into the skin, our serum leaves it feeling cared for and firm. The perfect partner for the coffee soap in your body ritual.</p><ul><li>Can visibly smooth the look of the skin</li><li>For a firm, cared-for feel</li><li>Easy to massage in</li></ul>', '<h2>عناية لمظهر بشرة أكثر نعومة</h2><p>يُدلك السيروم على البشرة فيمنحها إحساسًا بالعناية والشد. الرفيق المثالي لصابون القهوة في طقس العناية بالجسم.</p><ul><li>قد يحسن مظهر البشرة بشكل ملحوظ</li><li>لإحساس بالشد والعناية</li><li>سهل التدليك</li></ul>', '<ol><li>Einige Tropfen auf die gereinigte Haut geben.</li><li>Mit kreisenden Bewegungen einmassieren, bis es eingezogen ist.</li><li>Am besten täglich nach der Dusche anwenden.</li></ol>', '<ol><li>Apply a few drops to clean skin.</li><li>Massage in with circular movements until absorbed.</li><li>Best used daily after showering.</li></ol>', '<ol><li>ضعي بضع قطرات على بشرة نظيفة.</li><li>دلكي بحركات دائرية حتى يمتص.</li><li>يفضل استعماله يوميًا بعد الاستحمام.</li></ol>', '', 1550, 30, 'ml', '["/assets/p/serum-pack.webp", "/assets/p/serum-1.webp", "/assets/p/serum-2.webp", "/assets/p/serum-3.webp", "/assets/p/serum-4.webp"]', 1, 2, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('nila-seife', (SELECT id FROM categories WHERE slug = 'masken-peelings'), 'Nilla Seife', 'Nila soap', 'صابون النيلة · للوجه والجسم', 'Die blaue Seife der Wüste · 120 g', 'The blue soap of the desert · 120 g', 'الصابون الأزرق للصحراء · 120 غ', '<h2>Das blaue Geheimnis der Sahara</h2><p>Nila ist ein traditionelles Schönheitsmittel aus dem Süden Marokkos. Unsere Nila Seife für Gesicht und Körper bringt dieses Ritual in Ihr Badezimmer: für ein klares, strahlendes Hautgefühl.</p><ul><li>Für Gesicht und Körper</li><li>Traditionelles marokkanisches Schönheitsritual</li><li>120 g</li></ul>', '<h2>The blue secret of the Sahara</h2><p>Nila is a traditional beauty ingredient from southern Morocco. Our Nila soap for face and body brings this ritual into your bathroom, for skin that feels clear and radiant.</p><ul><li>For face and body</li><li>Traditional Moroccan beauty ritual</li><li>120 g</li></ul>', '<h2>السر الأزرق للصحراء</h2><p>النيلة مكون تجميلي تقليدي من جنوب المغرب. صابون النيلة للوجه والجسم يحمل هذا الطقس إلى حمامك، لبشرة صافية ومشرقة.</p><ul><li>للوجه والجسم</li><li>طقس جمال مغربي تقليدي</li><li>120 غ</li></ul>', '<ol><li>Auf die feuchte Haut auftragen und aufschäumen.</li><li>Kurz einwirken lassen und gründlich abspülen.</li></ol>', '<ol><li>Apply to damp skin and lather.</li><li>Leave on briefly, then rinse well.</li></ol>', '<ol><li>ضعيه على بشرة مبللة واصنعي رغوة.</li><li>اتركيه قليلًا ثم اشطفي جيدًا.</li></ol>', '', 1000, 120, 'g', '["/assets/p/nila-seife-1.webp", "/assets/p/nila-seife-2.webp"]', 1, 3, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('nila-peeling', (SELECT id FROM categories WHERE slug = 'masken-peelings'), 'Gommage (Peeling) Nilla', 'Nila gommage (scrub)', 'تقشير النيلة (غوماج)', 'Klärend & aufhellend · Für alle Hauttypen · 200 g', 'Clarifying & brightening · all skin types · 200 g', 'منقٍّ ومفتح · لجميع أنواع البشرة · 200 غ', '<h2>Für ein klares, strahlendes Hautbild</h2><p>Das Nila Peeling ist das Herzstück des marokkanischen Hammams. Es löst sanft abgestorbene Hautschüppchen und schenkt ein frisches, ebenmäßiges Hautgefühl.</p><ul><li>Klärend und aufhellend</li><li>Für alle Hauttypen</li><li>100 % natürlich</li></ul>', '<h2>For clear, radiant skin</h2><p>The Nila scrub is the heart of the Moroccan hammam. It gently removes dead skin and leaves the skin feeling fresh and even.</p><ul><li>Clarifying and brightening</li><li>For all skin types</li><li>100% natural</li></ul>', '<h2>لبشرة صافية ومشرقة</h2><p>تقشير النيلة هو قلب الحمام المغربي. يزيل الجلد الميت بلطف ويمنح البشرة إحساسًا بالانتعاش والتوحد.</p><ul><li>منقٍّ ومفتح</li><li>لجميع أنواع البشرة</li><li>طبيعي 100٪</li></ul>', '<ol><li>Eine kleine Menge auf die feuchte Haut geben.</li><li>Mit sanften, kreisenden Bewegungen einmassieren.</li><li>Gründlich abspülen. 1–2 Mal pro Woche anwenden.</li></ol>', '<ol><li>Apply a small amount to damp skin.</li><li>Massage in with gentle circular movements.</li><li>Rinse well. Use 1–2 times a week.</li></ol>', '<ol><li>ضعي كمية صغيرة على بشرة مبللة.</li><li>دلكي بحركات دائرية لطيفة.</li><li>اشطفي جيدًا. مرة أو مرتين في الأسبوع.</li></ol>', '', 1400, 200, 'g', '["/assets/p/nila-peeling-pack.webp"]', 0, 4, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('tebrima-mit-kraeutern', (SELECT id FROM categories WHERE slug = 'masken-peelings'), 'Tabrima', 'Tabrima herbal blend', 'التبريمة بالأعشاب', 'Traditionelle Kräutermischung · Für alle Hauttypen · 100 g', 'Traditional herbal blend · all skin types · 100 g', 'خليط أعشاب تقليدي · لجميع أنواع البشرة · 100 غ', '<h2>Die Kräuterpflege der Großmütter</h2><p>Tebrima ist eine traditionelle marokkanische Kräutermischung, die seit Generationen im Hammam verwendet wird. Als Maske angewendet, schenkt sie ein weiches, gepflegtes Hautgefühl und einen wunderbaren Duft.</p><ul><li>Traditionelle Kräutermischung</li><li>Für alle Hauttypen</li><li>100 g</li></ul>', '<h2>Grandmothers’ herbal care</h2><p>Tebrima is a traditional Moroccan herbal blend used in the hammam for generations. Applied as a mask, it leaves the skin feeling soft and cared for, with a wonderful scent.</p><ul><li>Traditional herbal blend</li><li>For all skin types</li><li>100 g</li></ul>', '<h2>عناية الجدات بالأعشاب</h2><p>التبريمة خليط أعشاب مغربي تقليدي يُستعمل في الحمام منذ أجيال. كقناع، تمنح البشرة نعومة وعناية ورائحة رائعة.</p><ul><li>خليط أعشاب تقليدي</li><li>لجميع أنواع البشرة</li><li>100 غ</li></ul>', '<ol><li>Etwas Pulver mit Wasser oder Rosenwasser zu einer Paste verrühren.</li><li>Auf Gesicht oder Körper auftragen und 10–15 Minuten einwirken lassen.</li><li>Mit warmem Wasser abspülen.</li></ol>', '<ol><li>Mix some powder with water or rose water into a paste.</li><li>Apply to face or body and leave on for 10–15 minutes.</li><li>Rinse with warm water.</li></ol>', '<ol><li>اخلطي قليلًا من المسحوق بالماء أو ماء الورد حتى يصبح عجينة.</li><li>ضعيها على الوجه أو الجسم واتركيها 10 إلى 15 دقيقة.</li><li>اشطفي بالماء الدافئ.</li></ol>', '', 1250, 100, 'g', '["/assets/p/tebrima-pack.webp", "/assets/p/tebrima-pack2.webp"]', 1, 5, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('henna-pulver', (SELECT id FROM categories WHERE slug = 'haar-kraeuter'), 'Henna-Pulver', 'Henna powder', 'مسحوق الحناء', 'Für Körper, Gesicht und Haar · 100 g', 'For body, face and hair · 100 g', 'للجسم والوجه والشعر · 100 غ', '<h2>Reines Henna aus Marokko</h2><p>Henna ist eines der ältesten Schönheitsmittel der Welt. Unser fein gemahlenes Henna Pulver eignet sich für die Haarpflege, für Körperkunst und traditionelle Rituale.</p><ul><li>Für Körper, Gesicht und Haar</li><li>Fein gemahlen</li><li>100 g</li></ul>', '<h2>Pure henna from Morocco</h2><p>Henna is one of the oldest beauty ingredients in the world. Our finely ground henna powder is suited to hair care, body art and traditional rituals.</p><ul><li>For body, face and hair</li><li>Finely ground</li><li>100 g</li></ul>', '<h2>حناء مغربية خالصة</h2><p>الحناء من أقدم مستحضرات الجمال في العالم. مسحوق الحناء المطحون بدقة مناسب للعناية بالشعر والنقش والطقوس التقليدية.</p><ul><li>للجسم والوجه والشعر</li><li>مطحون بدقة</li><li>100 غ</li></ul>', '<ol><li>Das Pulver mit warmem Wasser zu einer cremigen Paste verrühren und einige Stunden ruhen lassen.</li><li>Gleichmäßig auf das Haar auftragen, mit Folie abdecken und 1–3 Stunden einwirken lassen.</li><li>Gründlich ausspülen. Handschuhe tragen. Vorher einen Verträglichkeitstest machen.</li></ol>', '<ol><li>Mix the powder with warm water into a creamy paste and let it rest for a few hours.</li><li>Apply evenly to the hair, cover with film and leave on for 1–3 hours.</li><li>Rinse thoroughly. Wear gloves. Do a patch test first.</li></ol>', '<ol><li>اخلطي المسحوق بماء دافئ حتى يصبح عجينة كريمية واتركيه بضع ساعات.</li><li>ضعيه بالتساوي على الشعر، غطيه واتركيه من ساعة إلى ثلاث ساعات.</li><li>اشطفي جيدًا. استعملي القفازات. قومي باختبار الحساسية أولًا.</li></ol>', 'Lawsonia Inermis Leaf Powder', 650, 100, 'g', '["/assets/p/henna-pack.webp", "/assets/p/henna-1.webp", "/assets/p/henna-2.webp"]', 1, 6, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('sidr-pulver', (SELECT id FROM categories WHERE slug = 'haar-kraeuter'), 'Sidr-Pulver', 'Sidr powder', 'مسحوق السدر', 'Gleichmäßige, natürliche Textur · 100 g', 'Even, natural texture · 100 g', 'قوام طبيعي متجانس · 100 غ', '<h2>Die sanfte Pflanzenwäsche für Haar und Haut</h2><p>Sidr-Pulver wird aus den Blättern des Sidr-Baums (Christusdorn) gewonnen und ist seit Jahrhunderten Teil orientalischer Schönheitsrituale. Mit Wasser angerührt entsteht eine milde Paste für Haar und Haut.</p><ul><li>Gleichmäßige, natürliche Textur</li><li>Für Haar und Haut</li><li>100 g</li></ul>', '<h2>The gentle plant wash for hair and skin</h2><p>Sidr powder comes from the leaves of the sidr tree (Christ’s thorn) and has been part of Oriental beauty rituals for centuries. Mixed with water it makes a mild paste for hair and skin.</p><ul><li>Even, natural texture</li><li>For hair and skin</li><li>100 g</li></ul>', '<h2>الغسول النباتي اللطيف للشعر والبشرة</h2><p>يُستخرج مسحوق السدر من أوراق شجرة السدر، وهو جزء من طقوس الجمال الشرقية منذ قرون. يُخلط بالماء فيصبح عجينة لطيفة للشعر والبشرة.</p><ul><li>قوام طبيعي متجانس</li><li>للشعر والبشرة</li><li>100 غ</li></ul>', '<ol><li>2–3 Esslöffel Pulver mit warmem Wasser zu einer Paste verrühren.</li><li>Auf Haar oder Haut auftragen und 10–20 Minuten einwirken lassen.</li><li>Gründlich ausspülen.</li></ol>', '<ol><li>Mix 2–3 tablespoons of powder with warm water into a paste.</li><li>Apply to hair or skin and leave on for 10–20 minutes.</li><li>Rinse thoroughly.</li></ol>', '<ol><li>اخلطي 2 إلى 3 ملاعق من المسحوق بماء دافئ.</li><li>ضعيها على الشعر أو البشرة واتركيها 10 إلى 20 دقيقة.</li><li>اشطفي جيدًا.</li></ol>', 'Ziziphus Spina-Christi Leaf Powder', 800, 100, 'g', '["/assets/p/sidr-pack.webp", "/assets/p/sidr-1.webp", "/assets/p/sidr-2.webp"]', 1, 7, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('schwarze-seife-eukalyptus', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Schwarze Seife Eukalyptus', 'Black soap with eucalyptus', 'الصابون البلدي بالأوكالبتوس', 'Beldi-Seife für das Hammam · 200 g', 'Beldi soap for the hammam · 200 g', 'صابون بلدي للحمام · 200 غ', '<h2>Das Herz des marokkanischen Hammams</h2><p>Schwarze Seife (Savon Beldi) ist eine weiche, pastenartige Seife und der erste Schritt jedes Hammam-Rituals. Die Variante mit Eukalyptus duftet frisch und klärend.</p><ul><li>Mit Eukalyptus</li><li>Bereitet die Haut perfekt auf das Peeling vor</li><li>100 % natürlich</li></ul>', '<h2>The heart of the Moroccan hammam</h2><p>Black soap (savon beldi) is a soft, paste-like soap and the first step of every hammam ritual. The eucalyptus version has a fresh, clarifying scent.</p><ul><li>With eucalyptus</li><li>Prepares the skin perfectly for exfoliation</li><li>100% natural</li></ul>', '<h2>قلب الحمام المغربي</h2><p>الصابون البلدي صابون طري يشبه العجينة، وهو الخطوة الأولى في كل طقس حمام. نسخة الأوكالبتوس ذات رائحة منعشة ومنقية.</p><ul><li>بالأوكالبتوس</li><li>يهيئ البشرة للتقشير</li><li>طبيعي 100٪</li></ul>', '<ol><li>Eine kleine Menge auf die feuchte, warme Haut auftragen.</li><li>5–10 Minuten einwirken lassen (am besten im warmen Bad oder in der Dusche).</li><li>Abspülen und mit einem Kessa-Handschuh peelen.</li></ol>', '<ol><li>Apply a small amount to damp, warm skin.</li><li>Leave on for 5–10 minutes (ideally in a warm bath or shower).</li><li>Rinse and exfoliate with a kessa glove.</li></ol>', '<ol><li>ضعي كمية صغيرة على بشرة مبللة ودافئة.</li><li>اتركيه من 5 إلى 10 دقائق.</li><li>اشطفي ثم قشري بالكيس.</li></ol>', '', 1000, 200, 'g', '["/assets/p/schwarze-seife-eukalyptus-pack.webp"]', 1, 8, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('schwarze-seife-aker-fassi', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Schwarze Seife Aker Fasi', 'Black soap with aker fassi', 'الصابون البلدي بعكر الفاسي', 'Beldi-Seife mit Aker Fasi · 200 g', 'Beldi soap with aker fassi · 200 g', 'صابون بلدي بعكر الفاسي · 200 غ', '<h2>Schwarze Seife mit dem Rot von Fès</h2><p>Aker Fassi ist ein traditionelles Schönheitsmittel aus Fès, bekannt für seine leuchtend rote Farbe. In unserer schwarzen Seife verbindet es sich zu einem besonderen Hammam-Erlebnis.</p><ul><li>Mit Aker Fassi</li><li>Für das traditionelle Hammam-Ritual</li><li>100 % natürlich</li></ul>', '<h2>Black soap with the red of Fez</h2><p>Aker fassi is a traditional beauty ingredient from Fez, known for its bright red colour. In our black soap it creates a special hammam experience.</p><ul><li>With aker fassi</li><li>For the traditional hammam ritual</li><li>100% natural</li></ul>', '<h2>الصابون البلدي بأحمر فاس</h2><p>عكر الفاسي مستحضر جمال تقليدي من فاس معروف بلونه الأحمر الزاهي. يمتزج في صابوننا البلدي ليمنحك تجربة حمام مميزة.</p><ul><li>بعكر الفاسي</li><li>لطقس الحمام التقليدي</li><li>طبيعي 100٪</li></ul>', '<ol><li>Eine kleine Menge auf die feuchte, warme Haut auftragen.</li><li>5–10 Minuten einwirken lassen.</li><li>Abspülen und mit einem Kessa-Handschuh peelen.</li></ol>', '<ol><li>Apply a small amount to damp, warm skin.</li><li>Leave on for 5–10 minutes.</li><li>Rinse and exfoliate with a kessa glove.</li></ol>', '<ol><li>ضعي كمية صغيرة على بشرة مبللة ودافئة.</li><li>اتركيه من 5 إلى 10 دقائق.</li><li>اشطفي ثم قشري بالكيس.</li></ol>', '', 1000, 200, 'g', '["/assets/p/schwarze-seife-aker-fassi-pack.webp"]', 0, 9, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('aker-fassi-seife', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Aker Fasi Gesichtsseife', 'Aker fassi face soap', 'صابون عكر الفاسي للوجه', 'Handgemacht · 120 g', 'Handmade · 120 g', 'صنع يدوي · 120 غ', '<h2>Das Schönheitsgeheimnis aus Fès</h2><p>Unsere Aker-Fassi Seife für Gesicht und Körper trägt das traditionelle Rot aus Fès in Ihr tägliches Pflegeritual. Für ein frisches, gepflegtes Hautgefühl.</p><ul><li>Für Gesicht und Körper</li><li>Handgemacht</li><li>120 g</li></ul>', '<h2>The beauty secret of Fez</h2><p>Our aker fassi soap for face and body brings the traditional red of Fez into your daily care ritual, for skin that feels fresh and cared for.</p><ul><li>For face and body</li><li>Handmade</li><li>120 g</li></ul>', '<h2>سر الجمال من فاس</h2><p>صابون عكر الفاسي للوجه والجسم يحمل الأحمر التقليدي من فاس إلى روتين عنايتك اليومي، لبشرة منتعشة ومعتنى بها.</p><ul><li>للوجه والجسم</li><li>صنع يدوي</li><li>120 غ</li></ul>', '<ol><li>Mit Wasser aufschäumen und auf Gesicht oder Körper auftragen.</li><li>Sanft einmassieren und gründlich abspülen.</li></ol>', '<ol><li>Lather with water and apply to face or body.</li><li>Massage gently and rinse thoroughly.</li></ol>', '<ol><li>اصنعي رغوة بالماء وضعيها على الوجه أو الجسم.</li><li>دلكي بلطف ثم اشطفي جيدًا.</li></ol>', '', 1000, 120, 'g', '["/assets/p/aker-fassi-seife-1.webp"]', 0, 10, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('rizinusoel', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Rizinusöl', 'Castor oil', 'زيت الخروع', '100 % natürlich · Für Haar, Wimpern und Haut · 100 ml', '100% natural · for hair, lashes and skin · 100 ml', 'طبيعي 100٪ · للشعر والرموش والبشرة · 100 مل', '<h2>Das reichhaltige Pflegeöl für Haar und Haut</h2><p>Rizinusöl ist ein dickflüssiges, reichhaltiges Öl, das traditionell für die Pflege von Haar, Wimpern, Augenbrauen und trockener Haut verwendet wird.</p><ul><li>100 % natürlich</li><li>Für Haar, Wimpern, Augenbrauen und Haut</li><li>Praktische Pipettenflasche</li></ul>', '<h2>The rich care oil for hair and skin</h2><p>Castor oil is a thick, rich oil traditionally used to care for hair, lashes, brows and dry skin.</p><ul><li>100% natural</li><li>For hair, lashes, brows and skin</li><li>Practical dropper bottle</li></ul>', '<h2>زيت العناية الغني للشعر والبشرة</h2><p>زيت الخروع زيت كثيف وغني يُستعمل تقليديًا للعناية بالشعر والرموش والحواجب والبشرة الجافة.</p><ul><li>طبيعي 100٪</li><li>للشعر والرموش والحواجب والبشرة</li><li>قارورة عملية بقطارة</li></ul>', '<ol><li>Für das Haar: einige Tropfen in Kopfhaut und Spitzen einmassieren, mindestens 30 Minuten einwirken lassen und auswaschen.</li><li>Für Wimpern und Augenbrauen: abends mit einem sauberen Bürstchen sparsam auftragen.</li></ol>', '<ol><li>Hair: massage a few drops into scalp and ends, leave on for at least 30 minutes, then wash out.</li><li>Lashes and brows: apply sparingly in the evening with a clean brush.</li></ol>', '<ol><li>للشعر: دلكي بضع قطرات على فروة الرأس والأطراف، اتركيه 30 دقيقة على الأقل ثم اغسليه.</li><li>للرموش والحواجب: ضعيه مساءً بفرشاة نظيفة وبكمية قليلة.</li></ol>', 'Ricinus Communis Seed Oil', 1100, 100, 'ml', '["/assets/p/rizinusoel-pack.webp", "/assets/p/rizinusoel-1.webp", "/assets/p/rizinusoel-2.webp"]', 1, 11, 1);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('schwarze-seife-nilla', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Schwarze Seife Nilla', 'Black soap with nila', 'الصابون البلدي بالنيلة', 'Beldi-Seife mit Nila · 200 g', 'Beldi soap with nila · 200 g', 'صابون بلدي بالنيلة · 200 غ', '<h2>Schwarze Seife mit dem Blau der Wüste</h2><p>Unsere schwarze Beldi-Seife mit Nila verbindet den ersten Schritt des Hammam-Rituals mit dem traditionellen Schönheitsmittel aus dem Süden Marokkos.</p><ul><li>Mit Nila</li><li>Für das traditionelle Hammam-Ritual</li><li>200 g</li></ul>', '<h2>Black soap with the blue of the desert</h2><p>Our black beldi soap with nila combines the first step of the hammam ritual with the traditional beauty ingredient from southern Morocco.</p><ul><li>With nila</li><li>For the traditional hammam ritual</li><li>200 g</li></ul>', '<h2>الصابون البلدي بأزرق الصحراء</h2><p>صابوننا البلدي بالنيلة يجمع بين الخطوة الأولى في طقس الحمام والمكون التجميلي التقليدي من جنوب المغرب.</p><ul><li>بالنيلة</li><li>لطقس الحمام التقليدي</li><li>200 غ</li></ul>', '<ol><li>Eine kleine Menge auf die feuchte, warme Haut auftragen.</li><li>5–10 Minuten einwirken lassen.</li><li>Abspülen und mit einem Kessa-Handschuh peelen.</li></ol>', '<ol><li>Apply a small amount to damp, warm skin.</li><li>Leave on for 5–10 minutes.</li><li>Rinse and exfoliate with a kessa glove.</li></ol>', '<ol><li>ضعي كمية صغيرة على بشرة مبللة ودافئة.</li><li>اتركيه من 5 إلى 10 دقائق.</li><li>اشطفي ثم قشري بالكيس.</li></ol>', '', 1000, 200, 'g', '[]', 0, 12, 0);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('maske-nilla', (SELECT id FROM categories WHERE slug = 'masken-peelings'), 'Maske Nilla', 'Nila mask', 'قناع النيلة', 'Gesichtsmaske · 100 g', 'Face mask · 100 g', 'قناع للوجه · 100 غ', '<h2>Die blaue Maske für ein strahlendes Hautgefühl</h2><p>Die Nila Maske bringt das traditionelle Schönheitsritual der Sahara in Ihre Gesichtspflege.</p><ul><li>Mit Nila</li><li>100 g</li></ul>', '<h2>The blue mask for radiant-feeling skin</h2><p>The Nila mask brings the traditional beauty ritual of the Sahara into your face care.</p><ul><li>With nila</li><li>100 g</li></ul>', '<h2>القناع الأزرق لبشرة مشرقة</h2><p>قناع النيلة يحمل طقس الجمال التقليدي للصحراء إلى عنايتك بوجهك.</p><ul><li>بالنيلة</li><li>100 غ</li></ul>', '<ol><li>Auf das gereinigte Gesicht auftragen, Augenpartie aussparen.</li><li>10–15 Minuten einwirken lassen.</li><li>Mit lauwarmem Wasser abspülen.</li></ol>', '<ol><li>Apply to clean face, avoiding the eye area.</li><li>Leave on for 10–15 minutes.</li><li>Rinse with lukewarm water.</li></ol>', '<ol><li>ضعيه على وجه نظيف مع تجنب محيط العينين.</li><li>اتركيه من 10 إلى 15 دقيقة.</li><li>اشطفي بماء فاتر.</li></ol>', '', 1300, 100, 'g', '[]', 0, 13, 0);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('kessa-handschuh-schwarz', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Kiss Noir · Kessa-Handschuh Schwarz', 'Kiss noir · black kessa glove', 'الكيس الأسود', 'Der traditionelle Peeling-Handschuh für das Hammam', 'The traditional hammam exfoliating glove', 'كيس التقشير التقليدي للحمام', '<h2>Für das echte Hammam-Gefühl</h2><p>Der Kessa-Handschuh ist der treue Begleiter der schwarzen Seife: Nach dem Einwirken löst er abgestorbene Hautschüppchen und hinterlässt ein samtweiches Hautgefühl.</p>', '<h2>For the real hammam feeling</h2><p>The kessa glove is black soap’s faithful companion: after the soap has worked, it removes dead skin and leaves the skin feeling velvet-soft.</p>', '<h2>لإحساس الحمام الحقيقي</h2><p>الكيس رفيق الصابون البلدي: بعد ترك الصابون، يزيل الجلد الميت ويترك البشرة ناعمة كالحرير.</p>', '<ol><li>Nach der schwarzen Seife den Handschuh anfeuchten.</li><li>Die Haut mit festen Bewegungen abreiben.</li><li>Nach Gebrauch ausspülen und trocknen lassen.</li></ol>', '<ol><li>After the black soap, wet the glove.</li><li>Rub the skin with firm strokes.</li><li>Rinse and let it dry after use.</li></ol>', '<ol><li>بعد الصابون البلدي بللي الكيس.</li><li>افركي البشرة بحركات قوية.</li><li>اشطفيه واتركيه يجف بعد الاستعمال.</li></ol>', '', 600, NULL, '', '[]', 0, 14, 0);
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('khol-flasche', NULL, 'Khol Flasche', 'Kohl bottle', 'قارورة الكحل', '', '', '', '', '', '', '', '', '', '', 0, NULL, '', '[]', 0, 15, 0);
INSERT INTO posts (slug, cover, title_de, title_en, title_ar, excerpt_de, excerpt_en, excerpt_ar, body_de, body_en, body_ar) VALUES ('hammam-ritual-zu-hause', '/assets/p/serum-3.webp', 'Das marokkanische Hammam-Ritual für zu Hause', 'The Moroccan hammam ritual at home', 'طقس الحمام المغربي في بيتك', 'So holen Sie sich das Hammam nach Hause: mit schwarzer Seife, Peeling, Maske und Öl in fünf einfachen Schritten.', 'Bring the hammam home: black soap, scrub, mask and oil in five simple steps.', 'كيف تحضرين الحمام إلى بيتك: الصابون البلدي والتقشير والقناع والزيت في خمس خطوات بسيطة.', '<p>In Marokko ist das Hammam viel mehr als ein Bad: Es ist ein Ort der Ruhe, der Begegnung und der Pflege. Mit ein paar natürlichen Produkten können Sie dieses Ritual ganz einfach zu Hause genießen.</p><h2>1. Wärme</h2><p>Duschen oder baden Sie einige Minuten warm, damit sich die Poren öffnen.</p><h2>2. Schwarze Seife</h2><p>Tragen Sie die schwarze Seife auf die feuchte Haut auf und lassen Sie sie 5–10 Minuten einwirken.</p><h2>3. Peeling</h2><p>Spülen Sie die Seife ab und peelen Sie die Haut mit einem Kessa-Handschuh oder unserem Nila Peeling.</p><h2>4. Maske</h2><p>Eine Maske aus Tebrima oder Sidr beruhigt die Haut. 10–15 Minuten einwirken lassen und abspülen.</p><h2>5. Öl</h2><p>Zum Abschluss ein paar Tropfen Öl oder Serum einmassieren. Jetzt heißt es: zurücklehnen und genießen.</p>', '<p>In Morocco the hammam is much more than a bath: it is a place of calm, of meeting and of care. With a few natural products you can easily enjoy this ritual at home.</p><h2>1. Warmth</h2><p>Take a warm shower or bath for a few minutes to open the pores.</p><h2>2. Black soap</h2><p>Apply black soap to damp skin and leave it on for 5–10 minutes.</p><h2>3. Scrub</h2><p>Rinse and exfoliate with a kessa glove or our Nila scrub.</p><h2>4. Mask</h2><p>A Tebrima or sidr mask soothes the skin. Leave on for 10–15 minutes and rinse.</p><h2>5. Oil</h2><p>Finish by massaging in a few drops of oil or serum. Then lean back and enjoy.</p>', '<p>في المغرب، الحمام أكثر من مجرد استحمام: إنه مكان للراحة واللقاء والعناية. ببعض المنتجات الطبيعية يمكنك الاستمتاع بهذا الطقس في بيتك.</p><h2>1. الدفء</h2><p>استحمي بماء دافئ لبضع دقائق لتتفتح المسام.</p><h2>2. الصابون البلدي</h2><p>ضعي الصابون البلدي على بشرة مبللة واتركيه من 5 إلى 10 دقائق.</p><h2>3. التقشير</h2><p>اشطفي ثم قشري بالكيس أو بتقشير النيلة.</p><h2>4. القناع</h2><p>قناع التبريمة أو السدر يهدئ البشرة. اتركيه 10 إلى 15 دقيقة ثم اشطفي.</p><h2>5. الزيت</h2><p>في الختام دلكي بضع قطرات من الزيت أو السيروم، ثم استرخي واستمتعي.</p>');
INSERT INTO posts (slug, cover, title_de, title_en, title_ar, excerpt_de, excerpt_en, excerpt_ar, body_de, body_en, body_ar) VALUES ('henna-fuer-die-haare', '/assets/p/henna-2.webp', 'Henna für die Haare: so gelingt es', 'Henna for hair: how to get it right', 'الحناء للشعر: الطريقة الصحيحة', 'Henna pflegt und färbt das Haar auf natürliche Weise. Unsere Tipps für eine gelungene Anwendung.', 'Henna cares for and colours hair naturally. Our tips for a successful application.', 'الحناء تعتني بالشعر وتلونه بطريقة طبيعية. نصائحنا لاستعمال ناجح.', '<p>Henna wird seit Jahrtausenden für die Haarpflege verwendet. Damit das Ergebnis gelingt, kommt es auf ein paar Kleinigkeiten an.</p><h2>Die richtige Paste</h2><p>Rühren Sie das Pulver mit warmem Wasser zu einer joghurtartigen Paste an und lassen Sie sie einige Stunden ruhen.</p><h2>Auftragen</h2><p>Tragen Sie Handschuhe und verteilen Sie die Paste gleichmäßig auf dem sauberen, feuchten Haar. Mit Folie abdecken.</p><h2>Einwirken und ausspülen</h2><p>Je nach gewünschter Intensität 1–3 Stunden einwirken lassen und gründlich mit Wasser ausspülen. Machen Sie vorher immer einen Verträglichkeitstest.</p>', '<p>Henna has been used for hair care for thousands of years. A few details make the difference.</p><h2>The right paste</h2><p>Mix the powder with warm water into a yoghurt-like paste and let it rest for a few hours.</p><h2>Applying</h2><p>Wear gloves and spread the paste evenly on clean, damp hair. Cover with film.</p><h2>Leave on and rinse</h2><p>Leave on for 1–3 hours depending on the intensity you want, then rinse thoroughly with water. Always do a patch test first.</p>', '<p>تُستعمل الحناء للعناية بالشعر منذ آلاف السنين. بعض التفاصيل تصنع الفرق.</p><h2>العجينة الصحيحة</h2><p>اخلطي المسحوق بماء دافئ حتى يصبح قوامه كالزبادي واتركيه بضع ساعات.</p><h2>التطبيق</h2><p>البسي القفازات ووزعي العجينة بالتساوي على شعر نظيف ومبلل، ثم غطيه.</p><h2>الانتظار والشطف</h2><p>اتركيها من ساعة إلى ثلاث ساعات حسب الكثافة المرغوبة ثم اشطفي جيدًا. قومي دائمًا باختبار الحساسية أولًا.</p>');

