INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('arganoel-kosmetik-100ml', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Arganöl Kosmetik 100 ml', 'Cosmetic argan oil 100 ml', 'زيت الأركان التجميلي 100 مل', '100 % rein · kaltgepresst · für Haut, Haar & Nägel · 100 ml', '100 % pure · cold-pressed · for skin, hair & nails · 100 ml', 'خالص 100 % · معصور على البارد · للبشرة والشعر والأظافر · 100 مل', '<h2>Das flüssige Gold Marokkos</h2><p>Reines Arganöl, kaltgepresst aus den Kernen der Arganfrucht und in unserer Frauenkooperative von Hand gewonnen. Ohne Zusätze und ohne Duftstoffe.</p><ul><li>Pflegt trockene Haut und macht sie geschmeidig</li><li>Für weiches, glänzendes Haar und gepflegte Spitzen</li><li>Für Nägel und Nagelhaut</li><li>100 % rein, kaltgepresst</li></ul>', '<h2>The liquid gold of Morocco</h2><p>Pure argan oil, cold-pressed from the kernels of the argan fruit and made by hand in our women’s cooperative. No additives and no fragrance.</p><ul><li>Cares for dry skin and leaves it supple</li><li>For soft, shiny hair and cared-for ends</li><li>For nails and cuticles</li><li>100 % pure, cold-pressed</li></ul>', '<h2>الذهب السائل للمغرب</h2><p>زيت أركان خالص معصور على البارد من نوى ثمرة الأركان، تستخرجه نساء تعاونيتنا يدويًا. بدون إضافات وبدون عطور.</p><ul><li>يغذي البشرة الجافة ويمنحها النعومة</li><li>لشعر ناعم ولامع وأطراف معتنى بها</li><li>للأظافر وجلدها</li><li>خالص 100 %، معصور على البارد</li></ul>', '<ol><li>Gesicht: 2–3 Tropfen auf die gereinigte, leicht feuchte Haut geben und sanft einmassieren.</li><li>Haar: einige Tropfen in die Spitzen geben, ins feuchte oder trockene Haar.</li><li>Körper und Nägel: nach dem Duschen einmassieren.</li></ol>', '<ol><li>Face: apply 2–3 drops to clean, slightly damp skin and massage in gently.</li><li>Hair: work a few drops into the ends, on damp or dry hair.</li><li>Body and nails: massage in after the shower.</li></ol>', '<ol><li>للوجه: ضعي 2 إلى 3 قطرات على بشرة نظيفة ورطبة قليلًا ودلكي بلطف.</li><li>للشعر: بضع قطرات على الأطراف، على شعر رطب أو جاف.</li><li>للجسم والأظافر: دلكي بعد الاستحمام.</li></ol>', 'Argania Spinosa Kernel Oil', 2400, 100, 'ml', '["/assets/p/argan-kosmetik-100.webp"]', 0, 17, 1) ON CONFLICT(slug) DO UPDATE SET category_id = excluded.category_id, name_de = excluded.name_de, name_en = excluded.name_en, name_ar = excluded.name_ar, subtitle_de = excluded.subtitle_de, subtitle_en = excluded.subtitle_en, subtitle_ar = excluded.subtitle_ar, desc_de = excluded.desc_de, desc_en = excluded.desc_en, desc_ar = excluded.desc_ar, usage_de = excluded.usage_de, usage_en = excluded.usage_en, usage_ar = excluded.usage_ar, ingredients = excluded.ingredients, price = excluded.price, unit_amount = excluded.unit_amount, unit_type = excluded.unit_type, images = excluded.images, featured = excluded.featured, sort = excluded.sort, active = excluded.active;
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('arganoel-lebensmittel-100ml', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Lebensmittel-Arganöl 100 ml', 'Culinary argan oil 100 ml', 'زيت الأركان الغذائي 100 مل', 'Geröstet · kaltgepresst · nativ extra · 100 ml', 'Roasted · cold-pressed · extra virgin · 100 ml', 'محمص · معصور على البارد · بكر ممتاز · 100 مل', '<h2>Der nussige Geschmack Marokkos</h2><p>Lebensmittel-Arganöl aus gerösteten Arganmandeln, kaltgepresst und in unserer Frauenkooperative hergestellt. Intensives, nussiges Aroma, typisch für die marokkanische Küche.</p><ul><li>Zum Verfeinern von Salaten, Couscous und Tajine</li><li>Klassisch zum Frühstück mit Brot oder als Amlou mit Mandeln und Honig</li><li>Nativ extra, erste Kaltpressung</li><li>Marokkanisches Produkt</li></ul>', '<h2>The nutty taste of Morocco</h2><p>Culinary argan oil from roasted argan kernels, cold-pressed and made in our women’s cooperative. An intense, nutty flavour, typical of Moroccan cooking.</p><ul><li>To finish salads, couscous and tagines</li><li>Traditionally with bread at breakfast, or as amlou with almonds and honey</li><li>Extra virgin, first cold pressing</li><li>Product of Morocco</li></ul>', '<h2>النكهة المغربية الأصيلة</h2><p>زيت أركان غذائي من لوز الأركان المحمص، معصور على البارد ومنتج في تعاونيتنا النسائية. نكهة قوية تشبه المكسرات، أساسية في المطبخ المغربي.</p><ul><li>لتتبيل السلطات والكسكس والطاجين</li><li>تقليديًا مع الخبز في الفطور أو في الأملو مع اللوز والعسل</li><li>بكر ممتاز، عصرة أولى على البارد</li><li>منتج مغربي</li></ul>', '<ol><li>Kalt verwenden: über Salate, Gemüse oder Couscous träufeln.</li><li>Nicht stark erhitzen, damit das Aroma erhalten bleibt.</li><li>Kühl, trocken und lichtgeschützt lagern. Nach dem Öffnen zügig verbrauchen.</li></ol>', '<ol><li>Use cold: drizzle over salads, vegetables or couscous.</li><li>Do not heat strongly, to keep the flavour.</li><li>Store cool, dry and away from light. Use soon after opening.</li></ol>', '<ol><li>يُستعمل باردًا: على السلطات أو الخضر أو الكسكس.</li><li>لا يُسخَّن بقوة للحفاظ على النكهة.</li><li>يُحفظ في مكان بارد وجاف بعيدًا عن الضوء، ويُستهلك سريعًا بعد الفتح.</li></ol>', '100 % Arganöl aus gerösteten Arganmandeln, kaltgepresst (nativ extra).', 1700, 100, 'ml', '["/assets/p/argan-food-100.webp"]', 0, 18, 1) ON CONFLICT(slug) DO UPDATE SET category_id = excluded.category_id, name_de = excluded.name_de, name_en = excluded.name_en, name_ar = excluded.name_ar, subtitle_de = excluded.subtitle_de, subtitle_en = excluded.subtitle_en, subtitle_ar = excluded.subtitle_ar, desc_de = excluded.desc_de, desc_en = excluded.desc_en, desc_ar = excluded.desc_ar, usage_de = excluded.usage_de, usage_en = excluded.usage_en, usage_ar = excluded.usage_ar, ingredients = excluded.ingredients, price = excluded.price, unit_amount = excluded.unit_amount, unit_type = excluded.unit_type, images = excluded.images, featured = excluded.featured, sort = excluded.sort, active = excluded.active;
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('arganoel-lebensmittel-250ml', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Lebensmittel-Arganöl 250 ml', 'Culinary argan oil 250 ml', 'زيت الأركان الغذائي 250 مل', 'Geröstet · kaltgepresst · nativ extra · 250 ml', 'Roasted · cold-pressed · extra virgin · 250 ml', 'محمص · معصور على البارد · بكر ممتاز · 250 مل', '<h2>Der nussige Geschmack Marokkos</h2><p>Lebensmittel-Arganöl aus gerösteten Arganmandeln, kaltgepresst und in unserer Frauenkooperative hergestellt. Intensives, nussiges Aroma, typisch für die marokkanische Küche.</p><ul><li>Zum Verfeinern von Salaten, Couscous und Tajine</li><li>Klassisch zum Frühstück mit Brot oder als Amlou mit Mandeln und Honig</li><li>Nativ extra, erste Kaltpressung</li><li>Marokkanisches Produkt</li></ul>', '<h2>The nutty taste of Morocco</h2><p>Culinary argan oil from roasted argan kernels, cold-pressed and made in our women’s cooperative. An intense, nutty flavour, typical of Moroccan cooking.</p><ul><li>To finish salads, couscous and tagines</li><li>Traditionally with bread at breakfast, or as amlou with almonds and honey</li><li>Extra virgin, first cold pressing</li><li>Product of Morocco</li></ul>', '<h2>النكهة المغربية الأصيلة</h2><p>زيت أركان غذائي من لوز الأركان المحمص، معصور على البارد ومنتج في تعاونيتنا النسائية. نكهة قوية تشبه المكسرات، أساسية في المطبخ المغربي.</p><ul><li>لتتبيل السلطات والكسكس والطاجين</li><li>تقليديًا مع الخبز في الفطور أو في الأملو مع اللوز والعسل</li><li>بكر ممتاز، عصرة أولى على البارد</li><li>منتج مغربي</li></ul>', '<ol><li>Kalt verwenden: über Salate, Gemüse oder Couscous träufeln.</li><li>Nicht stark erhitzen, damit das Aroma erhalten bleibt.</li><li>Kühl, trocken und lichtgeschützt lagern. Nach dem Öffnen zügig verbrauchen.</li></ol>', '<ol><li>Use cold: drizzle over salads, vegetables or couscous.</li><li>Do not heat strongly, to keep the flavour.</li><li>Store cool, dry and away from light. Use soon after opening.</li></ol>', '<ol><li>يُستعمل باردًا: على السلطات أو الخضر أو الكسكس.</li><li>لا يُسخَّن بقوة للحفاظ على النكهة.</li><li>يُحفظ في مكان بارد وجاف بعيدًا عن الضوء، ويُستهلك سريعًا بعد الفتح.</li></ol>', '100 % Arganöl aus gerösteten Arganmandeln, kaltgepresst (nativ extra).', 3700, 250, 'ml', '[]', 0, 19, 0) ON CONFLICT(slug) DO UPDATE SET category_id = excluded.category_id, name_de = excluded.name_de, name_en = excluded.name_en, name_ar = excluded.name_ar, subtitle_de = excluded.subtitle_de, subtitle_en = excluded.subtitle_en, subtitle_ar = excluded.subtitle_ar, desc_de = excluded.desc_de, desc_en = excluded.desc_en, desc_ar = excluded.desc_ar, usage_de = excluded.usage_de, usage_en = excluded.usage_en, usage_ar = excluded.usage_ar, ingredients = excluded.ingredients, price = excluded.price, unit_amount = excluded.unit_amount, unit_type = excluded.unit_type, images = excluded.images, featured = excluded.featured, sort = excluded.sort, active = excluded.active;

