-- Kessa photo, kohl bottle texts and photo, prickly pear scrub (Nov 2026).
UPDATE products SET images = '["/assets/p/kessa-schwarz-pack.webp"]', active = 1 WHERE slug = 'kessa-handschuh-schwarz';
UPDATE products SET name_de = 'Kohl-Flasche mit natürlichem Kohl', name_en = 'Kohl bottle with natural kohl', name_ar = 'مكحلة مع كحل طبيعي', subtitle_de = 'Handbemalte Holz-Mkahla · natürlicher Kohl aus Dattelkernen', subtitle_en = 'Hand-painted wooden mkahla · natural kohl from date stones', subtitle_ar = 'مكحلة خشبية مرسومة يدويًا · كحل طبيعي بنواة التمر', desc_de = '<h2>Ein Stück marokkanischer Tradition</h2><p>Die Mkahla ist die traditionelle Kohl-Flasche aus Marokko: aus Holz gedrechselt und von Hand bemalt, jedes Stück ein Unikat. Dazu ein Glas natürlicher Kohl aus gerösteten Dattelkernen.</p><ul><li>Handbemalte Kohl-Flasche aus Holz mit Applikator-Stäbchen</li><li>Natürlicher Kohl aus Dattelkernen</li><li>Schönes Geschenk und Dekorationsstück</li><li>Farben und Muster können von Stück zu Stück variieren</li></ul>', desc_en = '<h2>A piece of Moroccan tradition</h2><p>The mkahla is Morocco’s traditional kohl bottle: turned from wood and painted by hand, every piece unique. It comes with a jar of natural kohl made from roasted date stones.</p><ul><li>Hand-painted wooden kohl bottle with applicator stick</li><li>Natural kohl from date stones</li><li>A lovely gift and decorative piece</li><li>Colours and patterns vary from piece to piece</li></ul>', desc_ar = '<h2>قطعة من التراث المغربي</h2><p>المكحلة هي قارورة الكحل المغربية التقليدية: من الخشب المخروط ومرسومة باليد، وكل قطعة فريدة. ومعها علبة كحل طبيعي من نواة التمر المحمصة.</p><ul><li>مكحلة خشبية مرسومة يدويًا مع مِرْوَد</li><li>كحل طبيعي بنواة التمر</li><li>هدية جميلة وقطعة ديكور</li><li>تختلف الألوان والرسوم من قطعة لأخرى</li></ul>', usage_de = '<ol><li>Etwas Kohl in die Flasche füllen.</li><li>Das Stäbchen eintauchen und überschüssiges Pulver abklopfen.</li><li>Sanft entlang des Wimpernkranzes ziehen. Nur äußerlich anwenden, nicht direkt ins Auge.</li></ol>', usage_en = '<ol><li>Fill a little kohl into the bottle.</li><li>Dip the stick and tap off excess powder.</li><li>Draw gently along the lash line. External use only, not directly into the eye.</li></ol>', usage_ar = '<ol><li>ضعي قليلًا من الكحل في المكحلة.</li><li>اغمسي المرود وانفضي الزائد.</li><li>مرريه بلطف على حافة الرموش. للاستعمال الخارجي فقط.</li></ol>', images = '["/assets/p/khol-flasche-1.webp"]', category_id = (SELECT id FROM categories WHERE slug = 'masken-peelings'), active = 0 WHERE slug = 'khol-flasche';
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('scrub-kaktusfeige', (SELECT id FROM categories WHERE slug = 'masken-peelings'), 'Kaktusfeigen-Peeling (Scrub Prickly Pear) 200 g', 'Prickly pear scrub 200 g', 'مقشر التين الشوكي 200 غ', 'Körperpeeling · glättend & pflegend · 200 g', 'Body scrub · smoothing & nourishing · 200 g', 'مقشر للجسم · منعِّم ومغذٍّ · 200 غ', '<h2>Glatte, strahlende Haut mit der Kraft der Kaktusfeige</h2><p>Unser Kaktusfeigen-Peeling entfernt sanft abgestorbene Hautschüppchen und hinterlässt ein samtweiches, gepflegtes Hautgefühl. Inspiriert vom marokkanischen Hammam und von der Kaktusfeige, die in den Dörfern der Kooperative wächst.</p><ul><li>Sanftes Körperpeeling</li><li>Für glatte, geschmeidige Haut</li><li>Mit dem Duft der Kaktusfeige</li><li>200 g</li></ul>', '<h2>Smooth, radiant skin with the power of prickly pear</h2><p>Our prickly pear scrub gently removes dead skin and leaves the skin velvety soft and cared for. Inspired by the Moroccan hammam and the prickly pear that grows around the cooperative’s villages.</p><ul><li>Gentle body scrub</li><li>For smooth, supple skin</li><li>With the scent of prickly pear</li><li>200 g</li></ul>', '<h2>بشرة ناعمة ومشرقة بقوة التين الشوكي</h2><p>مقشر التين الشوكي يزيل خلايا الجلد الميتة بلطف ويترك البشرة ناعمة كالحرير. مستوحى من الحمام المغربي ومن التين الشوكي الذي ينمو في قرى التعاونية.</p><ul><li>مقشر لطيف للجسم</li><li>لبشرة ناعمة ومرنة</li><li>برائحة التين الشوكي</li><li>200 غ</li></ul>', '<ol><li>Auf die feuchte Haut auftragen.</li><li>Mit kreisenden Bewegungen einmassieren.</li><li>Gründlich abspülen. 1–2 Mal pro Woche.</li></ol>', '<ol><li>Apply to damp skin.</li><li>Massage in with circular movements.</li><li>Rinse well. 1–2 times a week.</li></ol>', '<ol><li>ضعيه على بشرة مبللة.</li><li>دلكي بحركات دائرية.</li><li>اشطفي جيدًا. مرة أو مرتين في الأسبوع.</li></ol>', '', 0, 200, 'g', '["/assets/p/scrub-kaktusfeige-pack.webp", "/assets/p/scrub-kaktusfeige-1.webp", "/assets/p/scrub-kaktusfeige-2.webp"]', 0, 20, 0) ON CONFLICT(slug) DO UPDATE SET images = excluded.images;

-- Real photos and prices: scrub, rosemary oil, prickly pear oil, prickly pear soap (Nov 2026).
UPDATE products SET images = '["/assets/p/scrub-kaktusfeige-kh.webp"]', price = 1800, active = 1, name_de = 'SCRUB Prickly Pear · Kaktusfeigen-Peeling 200 g' WHERE slug = 'scrub-kaktusfeige';
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('kaktusfeigenoel-50ml', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Prickly Pear Oil · Kaktusfeigenöl 50 ml', 'Prickly pear oil 50 ml', 'زيت التين الشوكي 50 مل', 'Das kostbare Öl aus den Kernen der Kaktusfeige · 50 ml', 'The precious oil from prickly pear seeds · 50 ml', 'الزيت الثمين من بذور التين الشوكي · 50 مل', '<h2>Eines der kostbarsten Öle Marokkos</h2><p>Für wenige Milliliter Kaktusfeigenöl braucht es die Kerne unzähliger Früchte. Das leichte, schnell einziehende Öl ist ein Klassiker der marokkanischen Gesichtspflege und schenkt der Haut ein geschmeidiges, gepflegtes Gefühl.</p><ul><li>Leichte Textur, zieht schnell ein</li><li>Für Gesicht, Hals und Dekolleté</li><li>Grüne Glasflasche mit Pipette</li><li>50 ml</li></ul>', '<h2>One of Morocco’s most precious oils</h2><p>A few millilitres of prickly pear oil take the seeds of countless fruits. This light, fast-absorbing oil is a classic of Moroccan facial care and leaves skin feeling supple and cared for.</p><ul><li>Light texture, absorbs quickly</li><li>For face, neck and décolleté</li><li>Green glass bottle with dropper</li><li>50 ml</li></ul>', '<h2>من أثمن الزيوت المغربية</h2><p>بضعة ملليلترات من زيت التين الشوكي تحتاج إلى بذور عدد كبير من الثمار. زيت خفيف سريع الامتصاص، من كلاسيكيات العناية بالوجه في المغرب، يترك البشرة ناعمة ومرنة.</p><ul><li>قوام خفيف وسريع الامتصاص</li><li>للوجه والرقبة والصدر</li><li>قارورة زجاجية خضراء بقطارة</li><li>50 مل</li></ul>', '<ol><li>Abends 2–3 Tropfen auf die gereinigte Haut geben.</li><li>Sanft einmassieren, bis das Öl eingezogen ist.</li></ol>', '<ol><li>In the evening, apply 2–3 drops to cleansed skin.</li><li>Massage in gently until absorbed.</li></ol>', '<ol><li>مساءً ضعي 2–3 قطرات على بشرة نظيفة.</li><li>دلكي بلطف حتى يمتص الزيت.</li></ol>', '', 3600, '50', 'ml', '["/assets/p/kaktusfeigenoel-50.webp"]', 1, 21, 1) ON CONFLICT(slug) DO UPDATE SET images = excluded.images, price = excluded.price, active = 1;
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('rosmarinoel-50ml', (SELECT id FROM categories WHERE slug = 'oele-seren'), 'Rosemary Oil · Rosmarinöl 50 ml', 'Rosemary oil 50 ml', 'زيت إكليل الجبل 50 مل', 'Pflegeöl für Haar und Kopfhaut · 50 ml', 'Care oil for hair and scalp · 50 ml', 'زيت للعناية بالشعر وفروة الرأس · 50 مل', '<h2>Das Kräuteröl für Ihr Haarritual</h2><p>Rosmarin gehört seit Generationen zu den marokkanischen Pflegeritualen für Haar und Kopfhaut. Unser Rosmarinöl macht die wöchentliche Kopfhautmassage zu einem kleinen Ritual mit frischem, kräuterigem Duft.</p><ul><li>Für Kopfhaut und Haar</li><li>Frischer Kräuterduft</li><li>Grüne Glasflasche mit Pipette</li><li>50 ml</li></ul>', '<h2>The herbal oil for your hair ritual</h2><p>Rosemary has been part of Moroccan hair and scalp rituals for generations. Our rosemary oil turns the weekly scalp massage into a little ritual with a fresh, herbal scent.</p><ul><li>For scalp and hair</li><li>Fresh herbal scent</li><li>Green glass bottle with dropper</li><li>50 ml</li></ul>', '<h2>زيت الأعشاب لطقس شعرك</h2><p>إكليل الجبل جزء من طقوس العناية بالشعر وفروة الرأس في المغرب منذ أجيال. زيتنا يجعل تدليك فروة الرأس الأسبوعي طقسًا صغيرًا برائحة عشبية منعشة.</p><ul><li>لفروة الرأس والشعر</li><li>رائحة أعشاب منعشة</li><li>قارورة زجاجية خضراء بقطارة</li><li>50 مل</li></ul>', '<ol><li>Einige Tropfen auf die Kopfhaut geben und sanft einmassieren.</li><li>Mindestens 30 Minuten oder über Nacht einwirken lassen, dann auswaschen. Augenkontakt vermeiden.</li></ol>', '<ol><li>Apply a few drops to the scalp and massage in gently.</li><li>Leave on for at least 30 minutes or overnight, then wash out. Avoid contact with eyes.</li></ol>', '<ol><li>ضعي بضع قطرات على فروة الرأس ودلكي بلطف.</li><li>اتركيه 30 دقيقة على الأقل أو طوال الليل ثم اغسليه. تجنبي ملامسة العينين.</li></ol>', '', 2000, '50', 'ml', '["/assets/p/rosmarinoel-50.webp"]', 1, 22, 1) ON CONFLICT(slug) DO UPDATE SET images = excluded.images, price = excluded.price, active = 1;
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active) VALUES ('kaktusfeigen-seife', (SELECT id FROM categories WHERE slug = 'seifen-hammam'), 'Solid Soap · Harte Seife Kaktusfeige', 'Solid soap · prickly pear', 'صابون صلب بالتين الشوكي', 'Handgemachte Seife mit Kaktusfeige', 'Handmade soap with prickly pear', 'صابون مصنوع يدويًا بالتين الشوكي', '<h2>Die Kaktusfeige für jeden Tag</h2><p>Unsere harte Seife mit Kaktusfeige wird von Hand gefertigt und reinigt sanft. Ein Stück marokkanisches Hammam für das tägliche Waschritual.</p><ul><li>Handgemacht</li><li>Mit Kaktusfeige</li><li>Für Gesicht und Körper</li></ul>', '<h2>Prickly pear for every day</h2><p>Our solid prickly pear soap is made by hand and cleanses gently. A piece of the Moroccan hammam for your daily washing ritual.</p><ul><li>Handmade</li><li>With prickly pear</li><li>For face and body</li></ul>', '<h2>التين الشوكي لكل يوم</h2><p>صابوننا الصلب بالتين الشوكي مصنوع يدويًا وينظف بلطف. قطعة من الحمام المغربي لطقس الغسل اليومي.</p><ul><li>مصنوع يدويًا</li><li>بالتين الشوكي</li><li>للوجه والجسم</li></ul>', '<ol><li>Mit warmem Wasser aufschäumen.</li><li>Sanft auf Gesicht oder Körper auftragen und gründlich abspülen.</li><li>Nach Gebrauch trocken lagern.</li></ol>', '<ol><li>Lather with warm water.</li><li>Apply gently to face or body and rinse well.</li><li>Keep dry between uses.</li></ol>', '<ol><li>اصنعي رغوة بالماء الدافئ.</li><li>ضعيها بلطف على الوجه أو الجسم واشطفي جيدًا.</li><li>احفظيه جافًا بعد الاستعمال.</li></ol>', '', 1000, NULL, '', '["/assets/p/kaktusfeigen-seife.webp"]', 1, 23, 1) ON CONFLICT(slug) DO UPDATE SET images = excluded.images, price = excluded.price, active = 1;

-- Kohl: set or single pieces (Mkahla 26 €, kohl jar 12,50 €, set 38,50 €).
UPDATE products SET price = 1250, options = '[{"name": {"de": "Ihre Auswahl", "en": "Your choice", "ar": "اختيارك"}, "type": "text", "values": [{"label": "Set: Mkahla + Kohl", "price": 2600, "tr": {"en": "Set: wooden mkahla + kohl jar", "ar": "المجموعة: مكحلة خشبية + علبة الكحل"}}, {"label": "Nur Mkahla (Holz)", "price": 1350, "tr": {"en": "Wooden mkahla only", "ar": "المكحلة الخشبية فقط"}}, {"label": "Nur Kohl im Glas", "price": 0, "tr": {"en": "Kohl jar only", "ar": "علبة الكحل فقط"}}]}]', images = '["/assets/p/kohl-set-1.webp", "/assets/p/khol-flasche-1.webp"]', name_de = 'Mkahla & natürlicher Kohl', name_en = 'Mkahla & natural kohl', name_ar = 'مكحلة وكحل طبيعي', subtitle_de = 'Handbemalte Holz-Mkahla · Kohl aus Dattelkernen · als Set oder einzeln', subtitle_en = 'Hand-painted wooden mkahla · kohl from date stones · as a set or single', subtitle_ar = 'مكحلة خشبية مرسومة يدويًا · كحل بنواة التمر · مجموعة أو قطعة واحدة', active = 1 WHERE slug = 'khol-flasche';

-- Prickly pear oil 30 ml (30 €), same texts as the 50 ml bottle.
INSERT INTO products (slug, category_id, name_de, name_en, name_ar, subtitle_de, subtitle_en, subtitle_ar, desc_de, desc_en, desc_ar, usage_de, usage_en, usage_ar, ingredients, price, unit_amount, unit_type, images, featured, sort, active)
SELECT 'kaktusfeigenoel-30ml', category_id, replace(name_de,'50 ml','30 ml'), replace(name_en,'50 ml','30 ml'), replace(name_ar,'50 مل','30 مل'), replace(subtitle_de,'50 ml','30 ml'), replace(subtitle_en,'50 ml','30 ml'), replace(subtitle_ar,'50 مل','30 مل'), replace(desc_de,'50 ml','30 ml'), replace(desc_en,'50 ml','30 ml'), replace(desc_ar,'50 مل','30 مل'), usage_de, usage_en, usage_ar, ingredients, 3000, 30, 'ml', '["/assets/p/kaktusfeigenoel-30.webp"]', 1, sort, 1 FROM products WHERE slug = 'kaktusfeigenoel-50ml'
ON CONFLICT(slug) DO UPDATE SET price = excluded.price, images = excluded.images, active = 1;
